if sys.platform == "win32":
    os.startfile(link)  # noqa: S606 - the link names the desktop app's own scheme
else:
    subprocess.run(["open" if sys.platform == "darwin" else "xdg-open", link], check=True, timeout=OPEN_LINK_SECONDS)

for state in MESSAGE_STATES:
    (self._folder / state / f"{message}.json").unlink(missing_ok=True)
return self

try:
    return self._state_file.read()
except JsonFileUnreadable as unreadable:
    if isinstance(unreadable.cause, PermissionError):
        raise unreadable.cause from unreadable
    return {}

for path in self._sent_in(SHOWN):
    record = JsonFile(path)
    sent = record.read()
    if is_busy and not sent.get("is_worked_on"):
        record.write({**sent, "is_worked_on": True})
    elif not is_busy and sent.get("is_worked_on"):
        self._move(path, DONE)

if self.clock() - state.get("title_read", 0) <= TITLE_READ_SECONDS:
    return {"title": state.get("title", ""), "title_read": state["title_read"], "transcript": state.get("transcript", "")}
transcript = self._transcript_kept_in(state)
return {"title": _latest_title(transcript), "title_read": self.clock(), "transcript": str(transcript or "")}

handled = sorted((path for state in (TAKEN, SHOWN, DONE, FAILED) for path in self._sent_in(state)), key=lambda path: path.name)
for path in handled[:-KEPT_MESSAGES]:
    path.unlink()

for _ in range(HELD_FILE_ATTEMPTS - 1):
    try:
        return operation()
    except PermissionError:
        time.sleep(HELD_FILE_PAUSE_SECONDS)
return operation()

if transcript is None:
    return ""
title = ""
with transcript.open(encoding="utf-8", errors="replace") as lines:
    # Most lines are messages; only a line naming the title is parsed.
    for line in lines:
        if TITLE_MARK in line:
            entry = json.loads(line)
            title = entry.get("customTitle", title) if entry.get("type") == TITLE_MARK else title
return title

if self.status is AppStatus.NOT_INSTALLED:
    self.install()
return self

try:
    ran = subprocess.run(
        [self._npm_command, *arguments], cwd=self.folder, capture_output=True, text=True, encoding="utf-8", errors="replace", timeout=NPM_SECONDS, stdin=subprocess.DEVNULL
    )
except subprocess.TimeoutExpired as slow:
    raise AppNotStarted(self, f"npm {' '.join(arguments)} took longer than {NPM_SECONDS} s") from slow
if ran.returncode != 0:
    raise AppNotStarted(self, _reason_of(ran.stderr or ran.stdout) or f"npm {' '.join(arguments)} exited with {ran.returncode}")

lines = output.strip().splitlines()
errors = [line for line in lines if "err" in line.lower()]
return "\n".join(errors[:REASON_LINES] if errors else lines[-REASON_LINES:])

const app = express()
app.use(onlyThisMachine(port))
app.use(express.json())
app.use(API_ROOT, cddRoutes(projects, [...boardRoutes, ...stageRoutes, ...ticketRoutes, ...fidelityProgressRoutes, ...sessionRoutes, ...practiceSessionOutputRoutes, ...backlogItemRoutes, ...chatRoutes, ...appRoutes, ...storyMapRoutes]))
// The Story UI editor answers on this server too, at its own page, so it shares the board's port and the board's
// state: its calls are the story map's generated routes above, and its page is the one its own folder builds.
app.use(STORY_MAP_PAGE, express.static(storyMapBuild))
app.get(`${STORY_MAP_PAGE}/*`, (_request, response) => {
  response.sendFile(join(storyMapBuild, 'index.html'))
})
// The built page names its hashed script, so its index changes with every build: an open page compares the page
// served here with the one it loaded, and reloads itself on a new one.
app.use(express.static(staticRoot))
app.get('*', (_request, response) => {
  response.sendFile(join(staticRoot, 'index.html'))
})
app.use(answerFailure)
return app

const own = chat.name || chat.id
const isShared = this.store.state.chats.some(other => other.id !== chat.id && (other.name || other.id) === own)
return isShared ? `${own} (${chat.id.slice(0, SHOWN_CHAT_ID)})` : own

const query = new URLSearchParams(search)
const name = query.get(REPORT_QUERY)
const slug = query.get(FIDELITY_QUERY)
if (!name || !slug) return
if (!this.store.state.board) await this.reader.refresh()
const ticket = this.board.tickets.find(shown => shown.name === name)
const progress = ticket?.progressNamed(slug)
if (!ticket || !progress) return this.store.toast(`The board has no ${slug} report for ${name}.`, true)
this.store.change({ selected: ticket.address })
await this.panels.openReport(ticket, progress)

void this.openLinkedReport(typeof location === 'undefined' ? '' : location.search)
const stopBoard = this.reader.startPolling()
const chatTimer = setInterval(() => void this.pollChats(), CHAT_POLL_MILLISECONDS)
void this.pollChats()
return () => {
  stopBoard()
  clearInterval(chatTimer)
}

if (this.isPollingChats) return
this.isPollingChats = true
await Promise.all([this.chat.refresh(), this.build.check()]).finally(() => {
  this.isPollingChats = false
})

const opened = await app.open()
if (!opened) return
if (opened.status !== 'running') {
  this.store.toast(`The ${opened.label} app is ${opened.status}: open it from the chat bar's status row, which starts it for that chat.`, true)
  return
}
const page = new URL(opened.url)
page.searchParams.set(PROJECT_QUERY, project)
this.openWindow(page.toString())

const chats = await ChatClientGenerated.list(this.api)
if (!chats) return
const { pickedChat } = this.store.state
const picked = chats.find(chat => chat.id === pickedChat)
this.store.change({ chats, targetChat: picked?.id ?? null })
await this.readMessages()

if (!worktree) {
  const { [ticket]: _given, ...starting } = this.store.state.startingChats
  this.store.change({ startingChats: starting })
  return
}
if (await ChatClientGenerated.open(this.api, worktree, newChatPrompt(ticket))) this.store.toast(`Confirm the folder and send in the Claude app to start the chat of ${ticket}`)

const assigned = this.assigning.get(ticket)
if (assigned === undefined) return read
if (assigned === read) this.assigning.delete(ticket)
return assigned

const chat = this.targetClient
const messages = chat ? await chat.messages() : []
if (messages) this.store.change({ messages })

this.chooseChat(chat)
const wait = this.target?.is_busy ? ' It goes in when this turn ends.' : ''
return this.send('fill', text, `Queued for the prompt of ${this.targetName}, for you to review: ${shortened(text)}${wait}`)

if (!this.store.state.targetChat) {
  if (this.canSend) this.store.toast('Pick the chat to send to in the chat list first.')
  return
}
await this.actOnTarget(async chat => {
  const isSent = await chat.send(kind, text)
  if (isSent) this.store.toast(sent)
  return isSent
})

cleaned = (name or "").strip()
if not cleaned:
    raise RepoNameRequiredError()
if visibility not in _VISIBILITIES:
    raise UnknownVisibilityError(visibility)
root = (Path(folder).expanduser().resolve() if folder else self.folder) / cleaned
steps = [self._create(root), self._ignore_as_cdd_does(root)]
if publish:
    steps.append(self._publish(root, visibility))
if install:
    steps.append(self._install_cdd(root))
steps.append(self._open_chat(root, cleaned) if start_chat else self._chat_instructions(root, cleaned))
return "\n".join(f"- {step}" for step in steps if step)

try:
    Chat.open(str(root), _FIRST_PROMPT)
except (OSError, subprocess.SubprocessError):
    return self._chat_instructions(root, name)
return f"Opened a new chat on {root} in the Claude app: send its first prompt there to open the main session."

return (
    f"Start a top-level chat on {root}: start_session with initiation user_asked, context fresh, cwd {root}, "
    f"use_worktree false, title {name!r}, and prompt {_FIRST_PROMPT!r}. Or open {Chat.link_to_new(str(root), _FIRST_PROMPT)}"
)

if not self.is_installed:
    return AppStatus.NOT_INSTALLED
return AppStatus.DOWN if self.port is None else AppStatus.RUNNING

if not self._package.exists() or not (self.folder / "node_modules").is_dir():
    return False
return not self._builds_a_page or (self.folder / "dist").is_dir()

const read = this.store.state.board ?? NOT_READ_YET
if (this.shown?.read !== read) this.shown = new BoardClient(read, this)
return this.shown

chosen = self.config.value(_REPOS_FOLDER)
if chosen:
    return Path(chosen)
return Repo.of_project(self.project).main_clone.root.parent
